import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        final int N = sc.nextInt();
        int[] Qn = new int[N];
        int[] An = new int[N];
        int[] Bn = new int[N];

        for (int i = 0; i < N; i++) {
            Qn[i] = sc.nextInt();
        }
        for (int i = 0; i < N; i++) {
            An[i] = sc.nextInt();
        }
        for (int i = 0; i < N; i++) {
            Bn[i] = sc.nextInt();
        }

        int maxServings = 0;

        for (int aServings = 0; aServings <= 1000000; aServings++) {
            boolean possible = true;
            int maxBServings = Integer.MAX_VALUE;

            for (int i = 0; i < N; i++) {
                if (An[i] * aServings > Qn[i]) {
                    possible = false;
                    break;
                }
                if (Bn[i] > 0) {
                    int bServings = (Qn[i] - An[i] * aServings) / Bn[i];
                    maxBServings = Math.min(maxBServings, bServings);
                }
            }

            if (!possible) {
                break;
            }

            maxServings = Math.max(maxServings, aServings + maxBServings);
        }

        System.out.println(maxServings);
    }
}
